import{_ as t,a,o as n,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Catalog Attribute — Create (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-attribute-create","title":"Create Attribute","description":"Create a new product attribute with optional translations and options. Returns the full attribute detail.","query":"mutation CreateAttribute($input: createAdminAttributeInput!) {\\n  createAdminAttribute(input: $input) {\\n    adminAttribute {\\n      id\\n      _id\\n      code\\n      type\\n      adminName\\n      isRequired\\n      isUnique\\n      valuePerLocale\\n      valuePerChannel\\n      isFilterable\\n      isConfigurable\\n      isVisibleOnFront\\n      isUserDefined\\n      swatchType\\n      position\\n      locale\\n      validation\\n      defaultValue\\n      isComparable\\n      enableWysiwyg\\n      regex\\n      createdAt\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"code\\": \\"color\\",\\n    \\"adminName\\": \\"Color\\",\\n    \\"type\\": \\"select\\",\\n    \\"isFilterable\\": true,\\n    \\"isConfigurable\\": true,\\n    \\"position\\": 5,\\n    \\"swatchType\\": \\"color\\",\\n    \\"translations\\": {\\n      \\"en\\": { \\"name\\": \\"Color\\" },\\n      \\"fr\\": { \\"name\\": \\"Couleur\\" }\\n    },\\n    \\"options\\": [\\n      {\\n        \\"adminName\\": \\"Red\\",\\n        \\"sortOrder\\": 1,\\n        \\"swatchValue\\": \\"#FF0000\\",\\n        \\"translations\\": { \\"en\\": { \\"label\\": \\"Red\\" }, \\"fr\\": { \\"label\\": \\"Rouge\\" } }\\n      },\\n      {\\n        \\"adminName\\": \\"Green\\",\\n        \\"sortOrder\\": 2,\\n        \\"swatchValue\\": \\"#00FF00\\",\\n        \\"translations\\": { \\"en\\": { \\"label\\": \\"Green\\" }, \\"fr\\": { \\"label\\": \\"Vert\\" } }\\n      },\\n      {\\n        \\"adminName\\": \\"Blue\\",\\n        \\"sortOrder\\": 3,\\n        \\"swatchValue\\": \\"#0000FF\\",\\n        \\"translations\\": { \\"en\\": { \\"label\\": \\"Blue\\" }, \\"fr\\": { \\"label\\": \\"Bleu\\" } }\\n      }\\n    ]\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminAttribute\\": {\\n      \\"adminAttribute\\": {\\n        \\"id\\": \\"/api/admin/catalog/attributes/50\\",\\n        \\"_id\\": 50,\\n        \\"code\\": \\"color\\",\\n        \\"type\\": \\"select\\",\\n        \\"adminName\\": \\"Color\\",\\n        \\"isRequired\\": 0,\\n        \\"isUnique\\": 0,\\n        \\"valuePerLocale\\": 0,\\n        \\"valuePerChannel\\": 0,\\n        \\"isFilterable\\": 1,\\n        \\"isConfigurable\\": 1,\\n        \\"isVisibleOnFront\\": 1,\\n        \\"isUserDefined\\": 1,\\n        \\"swatchType\\": \\"color\\",\\n        \\"position\\": 5,\\n        \\"locale\\": \\"en\\",\\n        \\"validation\\": null,\\n        \\"defaultValue\\": null,\\n        \\"isComparable\\": 0,\\n        \\"enableWysiwyg\\": 0,\\n        \\"regex\\": null,\\n        \\"createdAt\\": \\"2026-05-22T10:00:00+00:00\\",\\n        \\"updatedAt\\": \\"2026-05-22T10:00:00+00:00\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/attributes/attributes-create.md","filePath":"api/graphql-api/admin/catalog/attributes/attributes-create.md","lastUpdated":1789385991000}'),o={name:"api/graphql-api/admin/catalog/attributes/attributes-create.md"};function i(d,e,l,s,c,u){return n(),a("div",null,e[0]||(e[0]=[r('<h1 id="catalog-attribute-—-create-graphql" tabindex="-1">Catalog Attribute — Create (GraphQL) <a class="header-anchor" href="#catalog-attribute-—-create-graphql" aria-label="Permalink to &quot;Catalog Attribute — Create (GraphQL)&quot;">​</a></h1><p>Creates a new product attribute. The <code>code</code> must be unique and pass the code rule (letters, digits, underscore) and may not be a reserved word. <code>code</code>, <code>adminName</code>, and <code>type</code> are required. For <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> types you may supply <code>options</code>; per-locale labels go under each option&#39;s <code>translations</code>. The mutation returns the full attribute detail.</p><p>See the <a href="/api/graphql-api/admin/catalog/attributes/">Attributes overview</a> for how attributes, options, and families fit together.</p><p>The nested <code>options</code> and their <code>translations</code> are not returned on the mutation payload — re-query <a href="/api/graphql-api/admin/catalog/attributes/attributes-detail.html"><code>adminAttribute</code></a> to read them back.</p><h2 id="validation-and-the-regex-pattern" tabindex="-1">Validation and the regex pattern <a class="header-anchor" href="#validation-and-the-regex-pattern" aria-label="Permalink to &quot;Validation and the regex pattern&quot;">​</a></h2><p><code>validation</code> names the rule a value must satisfy — <code>numeric</code>, <code>email</code>, <code>decimal</code>, <code>url</code> or <code>regex</code>. Choosing <code>regex</code> makes <code>regex</code> required, and the pattern is checked before it is stored.</p><p>A pattern must be delimited with <code>/</code>, may carry only the <code>i</code>, <code>m</code>, <code>s</code> and <code>u</code> modifiers, and must compile. That is narrower than PHP alone accepts because the same pattern is also written into the storefront&#39;s own form rules, where a <code>#</code> delimiter or a PCRE-only modifier would break the form for every product using the attribute. A pattern that does not qualify is refused rather than stored.</p>',7)]))}const h=t(o,[["render",i]]);export{m as __pageData,h as default};
